mapper.select:
SELECT *
FROM tb_price_history
WHERE fuel_type = #{fuelType}
  AND opinet_date BETWEEN #{from} AND #{to}
ORDER BY opinet_date DESC

SELECT COUNT(*) > 0
FROM tb_price_history
WHERE fuel_type = #{fuelType}
  AND opinet_date = #{opinetDate}

SELECT s.in_date AS metricDate, tk.fuel_type AS fuelType, AVG(s.buy_price) AS metricValue FROM tb_stock_in s JOIN tb_tank tk ON s.tank_id = tk.tank_id WHERE s.in_date BETWEEN #{from} AND #{to} AND tk.fuel_type IN
#{fuelType}
GROUP BY s.in_date, tk.fuel_type ORDER BY s.in_date ASC, tk.fuel_type ASC

SELECT DATE(t.tx_datetime) AS metricDate, tk.fuel_type AS fuelType, AVG(t.unit_price) AS metricValue FROM tb_transaction t JOIN tb_tank tk ON t.tank_id = tk.tank_id WHERE DATE(t.tx_datetime) BETWEEN #{from} AND #{to} AND tk.fuel_type IN
#{fuelType}
GROUP BY DATE(t.tx_datetime), tk.fuel_type ORDER BY metricDate ASC, tk.fuel_type ASC

SELECT tk.fuel_type AS fuelType, AVG(s.buy_price) AS metricValue FROM tb_stock_in s INNER JOIN tb_tank tk ON s.tank_id = tk.tank_id INNER JOIN ( SELECT tk2.fuel_type AS ft, MAX(s2.in_date) AS max_in_date FROM tb_stock_in s2 INNER JOIN tb_tank tk2 ON s2.tank_id = tk2.tank_id WHERE tk2.fuel_type IN
#{fuelType}
AND s2.in_date < #{beforeDate} GROUP BY tk2.fuel_type ) latest ON latest.ft = tk.fuel_type AND latest.max_in_date = s.in_date WHERE tk.fuel_type IN
#{fuelType}
GROUP BY tk.fuel_type

SELECT our_price
FROM tb_price_history
WHERE fuel_type = #{fuelType}
  AND opinet_date <= #{asOfDate}
ORDER BY opinet_date DESC
LIMIT 1
